# -*- coding: utf-8 -*-
"""الدفعة الثانية من الأدوات: مالية إضافية، مبيعات، ريادة، إنتاجية، وغيرها."""
from biz_tools import F, S, add, CATS, T
CATS['sales'] = ('🤝', 'المبيعات', 'عمولات وأهداف وخط مبيعات ورسائل بيع.')
CATS['startup'] = ('🚀', 'ريادة الأعمال', 'نموذج العمل وتكاليف التأسيس والتمويل والعرض التقديمي.')
CATS['productivity'] = ('⚡', 'الإنتاجية والتعلّم', 'خطط دراسة وأهداف وإدارة وقت وبرومتات للكتابة والتعلم.')
CATS['personal'] = ('🏠', 'المالية الشخصية', 'ميزانية وادخار وسداد ديون واستثمار.')

# ---------- finance ----------
add('depreciation', 'finance', '🏭', 'حاسبة الإهلاك (القسط الثابت والمتناقص)', 'جدول إهلاك أصل لمدة عمره.',
 [F('c', 'تكلفة الأصل', 'n', 50000), F('s', 'القيمة التخريدية', 'n', 5000), F('y', 'العمر بالسنوات', 'n', 5), S('m', 'الطريقة', [('sl', 'القسط الثابت'), ('db', 'القسط المتناقص (ضعف الثابت)')])],
 r'''function compute(v){const n=Math.max(1,Math.round(v.y));let bv=v.c,rows=[];for(let i=1;i<=n;i++){let d;if(v.m==='sl')d=(v.c-v.s)/n;else{d=Math.min(bv*2/n,bv-v.s);if(i===n)d=bv-v.s}d=Math.max(0,d);bv-=d;rows.push([i,f(d),f(bv)])}return tbl(['السنة','الإهلاك','القيمة الدفترية'],rows)+note('الطريقة الضريبية المعتمدة قد تختلف. راجع محاسبك.')}''')
add('inventory-valuation', 'finance', '📦', 'تقييم المخزون: المتوسط مقابل الوارد أولًا FIFO', 'قارن تكلفة المبيعات بالطريقتين.',
 [F('p', 'المشتريات (كمية | تكلفة الوحدة) بالترتيب الزمني', 'textarea', '100 | 10\n100 | 12\n100 | 14', r=4), F('q', 'الكمية المباعة', 'n', 150)],
 r'''function compute(v){const P=lines(v.p).map(r=>[num(r[0]),num(r[1])]);const tq=P.reduce((a,r)=>a+r[0],0),tc=P.reduce((a,r)=>a+r[0]*r[1],0);const avg=tq?tc/tq:0;let left=v.q,fifo=0;for(const r of P){const t=Math.min(left,r[0]);fifo+=t*r[1];left-=t;if(left<=0)break}const avgC=v.q*avg;
return kpis([kpi('تكلفة المبيعات (متوسط)',f(avgC)),kpi('تكلفة المبيعات (FIFO)',f(fifo)),kpi('مخزون آخر المدة (متوسط)',f(tc-avgC)),kpi('مخزون آخر المدة (FIFO)',f(tc-fifo))])+note('عند ارتفاع الأسعار يعطي FIFO تكلفة أقل وربحًا أعلى. الطريقة المسموحة تخضع للمعايير المحاسبية والضريبية.')}''')
add('working-capital-cycle', 'finance', '🔄', 'دورة رأس المال العامل', 'أيام التحصيل والمخزون والسداد ودورة تحويل النقد.',
 [F('rv', 'الإيرادات السنوية', 'n', 1200000), F('cg', 'تكلفة المبيعات السنوية', 'n', 700000), F('ar', 'الذمم المدينة', 'n', 150000), F('inv', 'المخزون', 'n', 120000), F('ap', 'الذمم الدائنة', 'n', 80000)],
 r'''function compute(v){const dso=v.rv?v.ar/v.rv*365:0,dio=v.cg?v.inv/v.cg*365:0,dpo=v.cg?v.ap/v.cg*365:0;const ccc=dso+dio-dpo;
return kpis([kpi('أيام التحصيل DSO',f(dso,0)),kpi('أيام المخزون DIO',f(dio,0)),kpi('أيام السداد DPO',f(dpo,0)),kpi('دورة تحويل النقد',f(ccc,0)+' يوم',ccc>60?'bad':'good')])+note('كلما قصرت الدورة قلّ المال المجمّد. قلّل التحصيل والمخزون وفاوض على أيام السداد.')}''')
add('markup-margin-converter', 'finance', '🔁', 'محوّل الهامش والإضافة', 'حوّل بين نسبة الهامش ونسبة الإضافة (Markup) وسعر البيع.',
 [F('c', 'التكلفة', 'n', 100), F('v', 'النسبة %', 'n', 30), S('t', 'نوع النسبة', [('mg', 'هامش (من سعر البيع)'), ('mk', 'إضافة (من التكلفة)')])],
 r'''function compute(v){let p,mg,mk;if(v.t==='mg'){p=v.c/(1-v.v/100);mg=v.v;mk=(p-v.c)/v.c*100}else{p=v.c*(1+v.v/100);mk=v.v;mg=(p-v.c)/p*100}
return kpis([kpi('سعر البيع',f(p),'good'),kpi('الهامش',f(mg,1)+'%'),kpi('الإضافة',f(mk,1)+'%'),kpi('الربح للوحدة',f(p-v.c))])+note('الهامش لا يتجاوز 100%، أما الإضافة فيمكن أن تتجاوزه.')}''')
add('discount-calculator', 'finance', '🏷️', 'حاسبة الخصومات المتتالية', 'السعر بعد خصم أو أكثر وأثره على هامشك.',
 [F('p', 'السعر الأصلي', 'n', 200), F('d1', 'الخصم الأول %', 'n', 20), F('d2', 'خصم إضافي %', 'n', 10), F('mg', 'هامشك الأصلي %', 'n', 40)],
 r'''function compute(v){const f1=v.p*(1-v.d1/100),f2=f1*(1-v.d2/100);const tot=(1-f2/v.p)*100;const cost=v.p*(1-v.mg/100);const nm=f2?(f2-cost)/f2*100:0;
return kpis([kpi('بعد الخصم الأول',f(f1)),kpi('السعر النهائي',f(f2),'good'),kpi('الخصم الفعلي',f(tot,1)+'%'),kpi('هامشك الجديد',f(nm,1)+'%',nm<10?'bad':'good')])+note('الخصمان المتتاليان 20% و10% لا يساويان 30% بل أقل.')}''')
add('cost-plus-pricing', 'finance', '🧮', 'التسعير بالتكلفة الشاملة', 'وزّع التكاليف الثابتة على الوحدات وأضف ربحك.',
 [F('v', 'تكلفة متغيرة للوحدة', 'n', 30), F('fx', 'تكاليف ثابتة شهرية', 'n', 6000), F('u', 'وحدات متوقعة شهريًا', 'n', 400), F('m', 'ربح مستهدف %', 'n', 25)],
 r'''function compute(v){const full=v.v+(v.u?v.fx/v.u:0);const p=full*(1+v.m/100);return kpis([kpi('التكلفة الشاملة للوحدة',f(full)),kpi('سعر البيع المقترح',f(p),'good'),kpi('ربح الوحدة',f(p-full))])+note('إن بعت أقل من الوحدات المتوقعة ارتفعت تكلفتك للوحدة. اختبر السعر بالسوق أيضًا.')}''')

# ---------- personal ----------
add('budget-50-30-20', 'personal', '🧾', 'ميزانية 50/30/20', 'وزّع دخلك على الاحتياجات والرغبات والادخار.',
 [F('i', 'الدخل الشهري الصافي', 'n', 9000), F('a', 'احتياجات % ', 'n', 50), F('b', 'رغبات %', 'n', 30), F('c', 'ادخار وسداد %', 'n', 20)],
 r'''function compute(v){const s=v.a+v.b+v.c;return tbl(['الفئة','النسبة','المبلغ'],[['احتياجات (سكن، غذاء، فواتير)',v.a+'%',f(v.i*v.a/100)],['رغبات (ترفيه، تسوق)',v.b+'%',f(v.i*v.b/100)],['ادخار وسداد ديون',v.c+'%',f(v.i*v.c/100)]])+(s!==100?'<p style="color:#c2410c">⚠️ مجموع النسب '+s+'% وليس 100%.</p>':'')+note('قاعدة إرشادية تناسب كثيرين، عدّلها حسب ظروفك.')}''')
add('savings-goal', 'personal', '🐖', 'حاسبة هدف الادخار', 'كم تدّخر شهريًا لتصل لهدفك؟',
 [F('g', 'المبلغ المستهدف', 'n', 60000), F('s', 'مدخراتك الحالية', 'n', 5000), F('m', 'المدة بالأشهر', 'n', 24), F('r', 'عائد سنوي متوقع %', 'n', 3)],
 r'''function compute(v){const n=Math.max(1,v.m),i=v.r/1200;const need=v.g-v.s*Math.pow(1+i,n);const pm=i?need*i/(Math.pow(1+i,n)-1):need/n;return kpis([kpi('الادخار الشهري المطلوب',f(Math.max(0,pm)),'good'),kpi('إجمالي ما تدفعه',f(Math.max(0,pm)*n))])+note('العائد غير مضمون. هذه حسابات تقديرية وليست نصيحة استثمارية.')}''')
add('debt-payoff', 'personal', '⛓️', 'مخطط سداد الديون', 'قارن طريقة كرة الثلج (الأصغر أولًا) بالانهيار (الأعلى فائدة).',
 [F('d', 'الديون (اسم | الرصيد | فائدة سنوية % | الحد الأدنى)', 'textarea', 'بطاقة | 8000 | 24 | 300\nقرض شخصي | 20000 | 8 | 600\nتقسيط | 3000 | 0 | 250', r=5), F('x', 'مبلغ إضافي شهري', 'n', 500)],
 r'''function compute(v){const base=lines(v.d).map(r=>({n:r[0],b:num(r[1]),r:num(r[2])/1200,m:num(r[3])}));function sim(order){const D=base.map(x=>({...x}));let mo=0,tint=0;while(D.some(x=>x.b>0.5)&&mo<600){mo++;let extra=v.x;D.forEach(x=>{if(x.b>0){const it=x.b*x.r;tint+=it;x.b+=it;const pay=Math.min(x.b,x.m);x.b-=pay;}});const act=D.filter(x=>x.b>0.5).sort(order);let free=D.reduce((a,x)=>a+(x.b<=0.5?x.m:0),0)+extra;
for(const x of act){if(free<=0)break;const pay=Math.min(x.b,free);x.b-=pay;free-=pay}}return[mo,tint]}
const s=sim((a,b)=>a.b-b.b),a=sim((a,b)=>b.r-a.r);return tbl(['الطريقة','المدة (أشهر)','إجمالي الفوائد'],[['كرة الثلج (الأصغر رصيدًا)',s[0],f(s[1],0)],['الانهيار (الأعلى فائدة)',a[0],f(a[1],0)]])+note('الانهيار يوفّر فوائد أكثر غالبًا، والثلج يحفّز نفسيًا. محاكاة مبسطة.')}''')
add('compound-growth', 'personal', '📈', 'حاسبة النمو المركّب', 'كيف ينمو مبلغ مع الادخار المنتظم؟',
 [F('p', 'المبلغ الابتدائي', 'n', 10000), F('m', 'إضافة شهرية', 'n', 500), F('r', 'عائد سنوي %', 'n', 6), F('y', 'السنوات', 'n', 10)],
 r'''function compute(v){let b=v.p,i=v.r/1200,rows=[];for(let m=1;m<=v.y*12;m++){b=b*(1+i)+v.m;if(m%12===0)rows.push([m/12,f(v.p+v.m*m),f(b)])}return kpis([kpi('القيمة النهائية',f(b),'good'),kpi('ما دفعته',f(v.p+v.m*v.y*12)),kpi('العائد',f(b-v.p-v.m*v.y*12))])+tbl(['السنة','المدفوع','القيمة'],rows.slice(0,15))+note('العوائد غير مضمونة وقد تكون سالبة. للتوضيح فقط.')}''')

# ---------- marketing ----------
add('ad-metrics-converter', 'marketing', '🔢', 'محوّل مؤشرات الإعلان', 'من CPM وCTR وCVR إلى CPC وCPA وROAS.',
 [F('cpm', 'CPM (تكلفة الألف ظهور)', 'n', 15), F('ctr', 'CTR %', 'n', 1.2), F('cvr', 'معدل التحويل %', 'n', 2.5), F('aov', 'متوسط قيمة الطلب', 'n', 150)],
 r'''function compute(v){const cpc=v.ctr?v.cpm/(1000*v.ctr/100):0;const cpa=v.cvr?cpc/(v.cvr/100):0;const roas=cpa?v.aov/cpa:0;return kpis([kpi('CPC',f(cpc)),kpi('CPA',f(cpa)),kpi('ROAS',f(roas),roas>=3?'good':'bad')])+note('ROAS مناسب يعتمد على هامشك. قارنه بـROAS التعادل.')}''')
add('influencer-roi', 'marketing', '🌟', 'حاسبة عائد التعاون مع مؤثر', 'هل يستحق المؤثر ما يطلبه؟',
 [F('f', 'تكلفة التعاون', 'n', 3000), F('rc', 'الوصول المتوقع', 'n', 50000), F('ctr', 'نسبة النقر %', 'n', 1), F('cv', 'التحويل %', 'n', 2), F('aov', 'قيمة الطلب', 'n', 150), F('mg', 'هامش الربح %', 'n', 40)],
 r'''function compute(v){const cl=v.rc*v.ctr/100,o=cl*v.cv/100,rev=o*v.aov,pr=rev*v.mg/100-v.f;return kpis([kpi('نقرات',f(cl,0)),kpi('طلبات',f(o,1)),kpi('إيراد',f(rev)),kpi('صافي العائد',f(pr),pr<0?'bad':'good')])+note('الوصول لا يساوي نقرات. اطلب أرقامًا فعلية سابقة وكود خصم خاصًا لتتبع المبيعات.')}''')
add('social-post-templates', 'marketing', '📱', 'قوالب منشورات التواصل', '8 قوالب منشورات جاهزة بمتغيراتك.',
 [F('p', 'المنتج/الخدمة', 't', 'خدمة التنظيف'), F('b', 'الفائدة', 't', 'بيت أنظف في ساعتين'), F('c', 'اسم العلامة', 't', 'نظافة+')],
 r'''function compute(v){const T=['سؤال: ما أكثر شيء يزعجك في '+v.p+'؟ شاركنا بتعليق 👇','نصيحة: 3 أخطاء شائعة في '+v.p+' وكيف تتجنبها.','قبل/بعد: شاهد الفرق مع '+v.c+' — '+v.b+'.','قصة: كيف بدأت '+v.c+' ولماذا؟','شهادة عميل: «…» — شكرًا لثقتكم 💜','سؤال وجواب: اسألنا عن '+v.p+' وسنجيب غدًا.','عرض: '+v.b+' مع '+v.c+' — اطلب اليوم.','وراء الكواليس: يوم عمل مع فريق '+v.c+'.'];
return T.map((t,i)=>'<pre class="tpl">'+(i+1)+') '+esc(t)+'</pre>').join('')}''')
add('slogan-name-prompts', 'marketing', '💡', 'مجهّز برومت الأسماء والشعارات', 'برومت لاقتراح أسماء وشعارات وهوية لعلامتك.',
 [F('b', 'وصف النشاط', 't', 'متجر منتجات عناية بالبشرة طبيعية'), F('a', 'الجمهور', 't', 'نساء 20-35'), F('v', 'القيم/النبرة', 't', 'أنيقة، موثوقة، طبيعية')],
 r'''function compute(v){return aiOut('أنت خبير تسمية علامات تجارية بالعربية.\nالنشاط: '+v.b+'\nالجمهور: '+v.a+'\nالقيم والنبرة: '+v.v+'\nاقترح 15 اسمًا (سهلة النطق، بدون معاني سلبية) مع سبب لكل اسم، ثم 5 شعارات لفظية (Slogans) لأفضل 3 أسماء. نبّهني لضرورة التحقق من توفر الاسم وتسجيله علامة تجارية.')}''', ai=True)

# ---------- sales ----------
add('sales-commission', 'sales', '💼', 'حاسبة عمولة المبيعات المتدرجة', 'عمولة بشرائح تتصاعد بحسب المبيعات.',
 [F('s', 'مبيعات الشهر', 'n', 120000), F('t', 'الشرائح (حتى مبلغ | نسبة %)', 'textarea', '50000 | 2\n100000 | 3\n999999999 | 5', r=4)],
 r'''function compute(v){let prev=0,rem=v.s,tot=0,rows=[];for(const r of lines(v.t)){const up=num(r[0]),p=num(r[1]);const amt=Math.max(0,Math.min(rem,up-prev));tot+=amt*p/100;rows.push([f(prev,0)+' - '+(up>1e8?'∞':f(up,0)),p+'%',f(amt,0),f(amt*p/100)]);rem-=amt;prev=up;if(rem<=0)break}return kpis([kpi('إجمالي العمولة',f(tot),'good'),kpi('النسبة الفعلية',v.s?f(tot/v.s*100,2)+'%':'-')])+tbl(['الشريحة','النسبة','المبلغ','العمولة'],rows)}''')
add('sales-target-planner', 'sales', '🎯', 'مخطط هدف المبيعات (الاتصالات والعملاء)', 'من هدف المبيعات إلى عدد الاتصالات المطلوبة.',
 [F('t', 'هدف المبيعات الشهري', 'n', 100000), F('d', 'متوسط قيمة الصفقة', 'n', 5000), F('c', 'نسبة إغلاق الصفقات %', 'n', 20), F('q', 'نسبة تحويل الاتصال إلى عميل مؤهل %', 'n', 15)],
 r'''function compute(v){const deals=Math.ceil(v.t/v.d),leads=Math.ceil(deals/(v.c/100)),calls=Math.ceil(leads/(v.q/100));return kpis([kpi('صفقات مطلوبة',deals),kpi('عملاء مؤهلون',leads),kpi('اتصالات',calls,'good'),kpi('اتصالات يوميًا (22 يوم)',f(calls/22,0))])+note('حسّن نسب التحويل قبل زيادة الجهد: تحسين 5 نقاط قد يوفّر مئات الاتصالات.')}''')
add('pipeline-forecast', 'sales', '🔭', 'توقع خط المبيعات', 'قدّر الإيراد المتوقع من الصفقات حسب مرحلتها.',
 [F('p', 'الصفقات (اسم | قيمة | احتمال %)', 'textarea', 'عميل أ | 20000 | 80\nعميل ب | 50000 | 40\nعميل ج | 10000 | 20', r=5)],
 r'''function compute(v){const L=lines(v.p).map(r=>[r[0],num(r[1]),num(r[2])]);const tot=L.reduce((a,r)=>a+r[1],0),w=L.reduce((a,r)=>a+r[1]*r[2]/100,0);return kpis([kpi('إجمالي الخط',f(tot)),kpi('المتوقع الموزون',f(w),'good'),kpi('عدد الصفقات',L.length)])+tbl(['الصفقة','القيمة','الاحتمال','الموزون'],L.map(r=>[esc(r[0]),f(r[1]),r[2]+'%',f(r[1]*r[2]/100)]))+note('اجعل الاحتمالات مبنية على بياناتك السابقة لكل مرحلة لا على التفاؤل.')}''')
add('sales-message-prompts', 'sales', '✉️', 'مجهّز برومت رسائل البيع', 'رسائل تعارف ومتابعة ومعالجة اعتراضات بالذكاء الاصطناعي.',
 [S('t', 'النوع', [('cold', 'رسالة تعارف أولى'), ('fu', 'رسالة متابعة'), ('ob', 'رد على اعتراض السعر'), ('cl', 'رسالة إغلاق')]), F('p', 'منتجك/خدمتك', 't', 'نظام إدارة مخزون للمتاجر'), F('c', 'العميل المستهدف', 't', 'أصحاب متاجر إلكترونية'), F('x', 'تفاصيل', 'textarea', '', r=3)],
 r'''function compute(v){const T={cold:'اكتب رسالة تعارف قصيرة (60 كلمة) تبدأ بمشكلة العميل لا بتعريفي، وتنتهي بسؤال بسيط.',fu:'اكتب رسالة متابعة محترمة بعد عدم رد، تضيف قيمة جديدة ولا تلوم.',ob:'اكتب رد على اعتراض «السعر مرتفع»: اسأل أولًا، ثم أعد صياغة القيمة، ثم قدّم خيارات.',cl:'اكتب رسالة إغلاق تلخص الاتفاق والخطوات التالية وموعدًا محددًا.'};return aiOut('أنت مستشار مبيعات يكتب بالعربية بنبرة محترمة وغير مُلحّة.\nالمنتج: '+v.p+'\nالعميل: '+v.c+'\nالمهمة: '+T[v.t]+'\nتفاصيل: '+(v.x||'-')+'\nقدّم نسختين وبدون مبالغات أو وعود غير مؤكدة.')}''', ai=True)
add('lead-scoring', 'sales', '🧲', 'تقييم جودة العميل المحتمل', 'درجة من 100 لأولوية المتابعة.',
 [S('b', 'الميزانية', [('3', 'مؤكدة وكافية'), ('2', 'محتملة'), ('1', 'غير واضحة')]), S('a', 'صاحب القرار', [('3', 'أنا أتحدث مع صاحب القرار'), ('2', 'مؤثر'), ('1', 'موظف لا يقرر')]), S('n', 'الحاجة', [('3', 'ملحّة'), ('2', 'موجودة'), ('1', 'غير واضحة')]), S('t', 'التوقيت', [('3', 'خلال شهر'), ('2', 'خلال 3 أشهر'), ('1', 'غير محدد')])],
 r'''function compute(v){const s=(num(v.b)+num(v.a)+num(v.n)+num(v.t));const p=Math.round((s-4)/8*100);return kpis([kpi('درجة العميل',p+'/100',p>=70?'good':'bad')])+'<p>'+(p>=70?'🔥 عميل ساخن: تواصل اليوم.':p>=40?'🟡 دافئ: تابع أسبوعيًا بمحتوى مفيد.':'❄️ بارد: ضعه في قائمة رعاية طويلة.')+'</p>'+note('نموذج BANT مبسط.')}''')

