add('startup-costs-runway', 'startup', '🛫', 'تكاليف التأسيس ومدة التشغيل (Runway)', 'كم تحتاج وكم تستمر؟',
 [F('t', 'تكاليف التأسيس (بند | مبلغ)', 'textarea', 'ترخيص وتسجيل | 3000\nموقع ومتجر | 5000\nمخزون أولي | 20000', r=4), F('c', 'رأس المال المتاح', 'n', 60000), F('b', 'الحرق الشهري (مصروفات - إيرادات)', 'n', 8000)],
 r'''function compute(v){const t=lines(v.t).reduce((a,r)=>a+num(r[1]||0),0);const rem=v.c-t;const run=v.b>0?rem/v.b:0;return kpis([kpi('تكاليف التأسيس',f(t,0)),kpi('المتبقي بعد التأسيس',f(rem,0),rem<0?'bad':'good'),kpi('مدة التشغيل (شهر)',v.b>0?f(run,1):'∞',run<6?'bad':'good')])+note('اجعل مدة التشغيل 6 أشهر على الأقل قبل الاطمئنان، وأضف هامشًا 15% لتكاليف غير متوقعة.')}''')
