 [S('a', 'المشكلة حقيقية؟', [('1', 'غير متأكد'), ('2', 'بعض العملاء قالوا'), ('3', 'عملاء دفعوا فعلًا')], '2'), S('b', 'حجم السوق', [('1', 'صغير جدًا'), ('2', 'متوسط'), ('3', 'كبير')], '2'), S('c', 'ميزتك التنافسية', [('1', 'لا شيء'), ('2', 'بسيطة'), ('3', 'واضحة وصعبة التقليد')], '2'), S('d', 'القدرة على التنفيذ', [('1', 'ضعيفة'), ('2', 'متوسطة'), ('3', 'قوية')], '2'), S('e', 'ربحية متوقعة', [('1', 'ضعيفة'), ('2', 'مقبولة'), ('3', 'جيدة')], '2')],
