add('pitch-deck-prompts', 'startup', '🎤', 'مجهّز برومت العرض التقديمي للمستثمر', 'هيكل عرض من 10 شرائح بالذكاء الاصطناعي.',
 [F('n', 'اسم المشروع', 't', 'مشروعي'), F('p', 'المشكلة والحل', 'textarea', '', r=3), F('m', 'السوق والنموذج المالي', 'textarea', '', r=3)],
 r'''function compute(v){return aiOut('أنت مستشار ريادة أعمال. ابنِ عرضًا تقديميًا للمستثمرين من 10 شرائح لمشروع «'+v.n+'»:\nالمشكلة والحل: '+(v.p||'اسألني')+'\nالسوق والنموذج: '+(v.m||'اسألني')+'\nلكل شريحة: عنوان، 3 نقاط، وملاحظات للمتحدث. اختم بقائمة أسئلة متوقعة من المستثمر. لا تختلق أرقام سوق؛ اطلب مني المصادر.')}''', ai=True)
add('valuation-simple', 'startup', '🏷️', 'تقدير قيمة مشروع بسيط', 'مضاعف الأرباح أو الإيرادات كتقدير أولي.',
 [F('rv', 'الإيرادات السنوية', 'n', 1200000), F('pf', 'صافي الربح السنوي', 'n', 180000), F('mr', 'مضاعف الإيرادات', 'n', 1), F('mp', 'مضاعف الأرباح', 'n', 4)],
 r'''function compute(v){const a=v.rv*v.mr,b=v.pf*v.mp;return kpis([kpi('بمضاعف الإيرادات',f(a,0)),kpi('بمضاعف الأرباح',f(b,0)),kpi('المتوسط',f((a+b)/2,0),'good')])+note('المضاعفات تختلف كثيرًا بين القطاعات والحجم. هذا تقدير أولي وليس تقييمًا مهنيًا.')}''')

