 [F('r', 'المخاطر (خطر | احتمال 1-5 | أثر 1-5 | إجراء)', 'textarea', 'تأخر المورد | 4 | 4 | مورد بديل\nارتفاع الشحن | 3 | 3 | عقد شحن\nفقد موظف رئيسي | 2 | 5 | توثيق وتدريب', r=5)],
