add('turnover-rate', 'hr', '🚪', 'معدل دوران الموظفين وكلفته', 'قياس الاستقالات وكلفتها المقدّرة.',
 [F('s', 'الموظفون أول الفترة', 'n', 40), F('e', 'الموظفون آخر الفترة', 'n', 42), F('l', 'من غادروا', 'n', 6), F('c', 'كلفة استبدال موظف (تقدير)', 'n', 15000)],
 r'''function compute(v){const avg=(v.s+v.e)/2,r=avg?v.l/avg*100:0;return kpis([kpi('معدل الدوران',f(r,1)+'%',r>20?'bad':'good'),kpi('كلفة الدوران',f(v.l*v.c,0),'bad')])+note('الكلفة تشمل التوظيف والتدريب والإنتاجية الضائعة. اسأل المغادرين عن الأسباب.')}''')
