 [F('t', 'المهارات (مهارة | عدد المتدربين | تكلفة للفرد)', 'textarea', 'خدمة العملاء | 5 | 400\nالإكسل | 8 | 250', r=4), F('b', 'الميزانية السنوية', 'n', 6000)],
